ORIGINAL_SOURCE = '\nvar Counter = {\n    i: 0,\n    w: 0,\n    f: 0\n};\n\n// Variables\nvar InitAccount = null;\n\nfunction CancelAll() {\n    while (true) {\n        var orders = _C(exchange.GetOrders);\n        if (orders.length == 0) {\n            break;\n        }\n        for (var i = 0; i < orders.length; i++) {\n            exchange.CancelOrder(orders[i].Id);\n        }\n        Sleep(Interval);\n    }\n}\n\nfunction updateStatus(msg) {\n    LogStatus("调戏次数:", Counter.i, "成功:", Counter.w, "失败:", Counter.f, "\\n"+msg+"#0000ff\\n"+new Date());\n}\n\nfunction main() {\n    if (DisableLog) {\n        EnableLog(false);\n    }\n    CancelAll();\n    InitAccount = _C(exchange.GetAccount);\n    Log(InitAccount);\n    var i = 0;\n    var locks = 0;\n    while (true) {\n        Sleep(Interval);\n        var depth = _C(exchange.GetDepth);\n        if (depth.Asks.length === 0 || depth.Bids.length === 0) {\n            continue;\n        }\n        updateStatus("搜索大象中.... 买一: " + depth.Bids[0].Price + ", \xa0卖一:" + depth.Asks[0].Price + ", 锁定次数: " + locks);\n        var askPrice = 0;\n        for (i = 0; i < depth.Asks.length; i++) {\n            if (depth.Asks[i].Amount >= Lot) {\n                askPrice = depth.Asks[i].Price;\n                break;\n            }\n        }\n        if (askPrice === 0) {\n            continue;\n        }\n        var elephant = null;\n        // skip Bids[0]\n        for (i = 1; i < depth.Bids.length; i++) {\n            if ((askPrice - depth.Bids[i].Price) > ElephantSpace) {\n                break;\n            }\n            if (depth.Bids[i].Amount >= ElephantAmount) {\n                elephant = depth.Bids[i];\n                break;\n            }\n        }\n\n        if (!elephant) {\n            locks = 0;\n            continue;\n        }\n        locks++;\n        if (locks < LockCount) {\n            continue;\n        }\n        locks = 0;\n\n        updateStatus("调戏大象中....大象在第" + i + "档, " + JSON.stringify(elephant));\n        exchange.Buy(elephant.Price + PennyTick, Lot, "Bids[" + i + "]", elephant);\n        var ts = new Date().getTime();\n        while (true) {\n            Sleep(CheckInterval);\n            var orders = _C(exchange.GetOrders);\n            if (orders.length == 0) {\n                break;\n            }\n            if ((new Date().getTime() - ts) > WaitInterval) {\n                for (var i = 0; i < orders.length; i++) {\n                    exchange.CancelOrder(orders[i].Id);\n                }\n            }\n        }\n        var account = _C(exchange.GetAccount);\n        var opAmount = _N(account.Stocks - InitAccount.Stocks);\n        if (opAmount < 0.001) {\n            Counter.f++;\n            Counter.i++;\n            continue;\n        }\n        updateStatus("买单得手: " + opAmount +", 开始出手...");\n        exchange.Sell(elephant.Price + (PennyTick * ProfitTick), opAmount);\n        var success = true;\n        while (true) {\n            var depth = _C(exchange.GetDepth);\n            if (depth.Bids.length > 0 && depth.Bids[0].Price <= (elephant.Price-(STTick*PennyTick))) {\n                success = false;\n                updateStatus("没有得手, 开始止损, 当前买一: " + depth.Bids[0].Price);\n                CancelAll();\n                account = _C(exchange.GetAccount);\n                var opAmount = _N(account.Stocks - InitAccount.Stocks);\n                if (opAmount < 0.001) {\n                    break;\n                }\n                exchange.Sell(depth.Bids[0].Price, opAmount);\n            }\n            var orders = _C(exchange.GetOrders);\n            if (orders.length === 0) {\n                break;\n            }\n            Sleep(CheckInterval);\n        }\n        if (success) {\n            Counter.w++;\n        } else {\n            Counter.f++;\n        }\n        Counter.i++;\n        var account = _C(exchange.GetAccount);\n        LogProfit(account.Balance - InitAccount.Balance, account);\n    }\n}\n'
